502	FileHashResult merkle_root_files(const std::vector<std::filesystem::path>& paths) {
503	    FileHashResult result;
504	
505	    // 没有文件：空字节序列的 SHA-256。
506	    if (paths.empty()) {
507	        result.digest = merkle_empty_root();
508	        return result;
509	    }
510	
511	    // 叶子层。
512	    std::vector<Digest> level;
513	    result.error = leaf_level(paths, level);
514	    if (!result.ok()) {
515	        return result;
516	    }
517	
518	    // 逐层相邻配对直到只剩一个根；配对与奇数末节点原样提升的规则由
519	    // combine_level 唯一实现，prove 沿同一函数走，两条路径不会出现规则漂移。
520	    while (level.size() > 1) {
521	        level = combine_level(level);
522	    }
523	
524	    result.digest = level.front();
525	    return result;
526	}
