    // 读取字段值位置上的 JSON 字符串。
    bool read_string_value(std::string& out, std::string_view field) {
        ws();
        if (eof()) {
            return fail(std::string("missing value for field \"") +
                        std::string(field) + "\"");
        }
        const char c = peek();
        if (c != '"') {
            return fail(std::string("field \"") + std::string(field) +
                        "\" must be a JSON string");
        }
        return read_string(out);
    }

    // 读取一个 JSON 对象的正文（起始 '{' 已被调用方消费，或由
    // parse_object 代为消费）。正文的结构规则对顶层证明对象与每条兄弟
    // 记录完全一致，因此只在此维护一份：
    //   * 允许 "{}" 空对象（必填字段是否齐全由调用方在回调中自行核对）；
    //   * 字段名按解码后的字符串识别（"root" 与 "root" 同名）；
    //   * 字段名后必须紧跟 ':'，字段值由调用方提供的 read_value 读取；
    //   * 字段之间以 ',' 分隔，读到 '}' 结束；
    //   * 键重复、未定义键以及分隔符损坏都在此或经 read_value 判错。
    //
