#include <sstream>
#include <string>

#include "merkle.h"

using branchaudit::Digest;
using branchaudit::MerkleProof;
using branchaudit::MerkleProofParseResult;

static std::string hex(const Digest& d) {
    static const char* h = "0123456789abcdef";
    std::string s;
    for (unsigned char b : d) {
        s.push_back(h[b >> 4]);
        s.push_back(h[b & 0xF]);
    }
    return s;
}

int main() {
    std::ostringstream ss;
    ss << std::cin.rdbuf();
    std::string text = ss.str();
    MerkleProofParseResult r = branchaudit::merkle_proof_from_json(text);
    if (!r.ok()) {
        std::cout << "ERR: " << r.error << "\n";
        return 0;
    }
    const MerkleProof& p = r.proof;
    std::cout << "OK version-structure\n";
    std::cout << "root=" << hex(p.root) << "\n";
    std::cout << "leaf_count=" << p.leaf_count << "\n";
    std::cout << "leaf_index=" << p.leaf_index << "\n";
    std::cout << "leaf=" << hex(p.leaf) << "\n";
    std::cout << "siblings=" << p.siblings.size() << "\n";
    for (const auto& s : p.siblings) {
        std::cout << (s.side == branchaudit::MerkleSibling::Side::left ? "L "
                                                                        : "R ")
                  << hex(s.digest) << "\n";
    }
    return 0;
}

