        if (c >= '0' && c <= '9') {
            v = static_cast<unsigned int>(c - '0');
            return true;
        }
        // 只接受小写：A-F 等大写字符在此失败，而不是被当作同一摘要。
        if (c >= 'a' && c <= 'f') {
            v = static_cast<unsigned int>(c - 'a' + 10);
            return true;
        }
        return false;
